 bool abandon(){if(!dirty)return true;int r=MessageBoxW(window,L"저장하지 않은 DB 변경이 있습니다. 저장할까요?",L"업무 정보 도우미",MB_YESNOCANCEL|MB_ICONQUESTION);if(r==IDCANCEL)return false;if(r==IDYES){save();return !dirty;}return true;}
