 void registerKey(const Shortcut& next,bool persist){next.validate();bool same=hotId&&config.shortcut.key==next.key&&config.shortcut.modifiers==next.modifiers;int nextId=hotId==4101?4102:4101;if(!same)require(RegisterHotKey(window,nextId,next.modifiers|MOD_NOREPEAT,next.key),"단축키를 등록할 수 없습니다. 다른 키를 선택하거나 PC 정책을 확인하세요.");Config candidate=config;candidate.shortcut=next;try{if(persist)candidate.save();}catch(...){if(!same)UnregisterHotKey(window,nextId);throw;}if(!same){if(hotId)UnregisterHotKey(window,hotId);hotId=nextId;}config=candidate;updateHotStatus();}
