 void display(const std::wstring& selected,bool interfaces,POINT anchor,HWND original){require(selected.size()<=10000,"조회 문자열은 최대 10,000자입니다.");Database data=hasSaved?Database::parse(asUtf8(read(config.database),Button_GetCheck(encoding)==BST_CHECKED)):(selfTest?working:Database{});auto found=data.lookup(utf8(selected),interfaces);std::unique_ptr<Result> result(new Result);result->original=original;result->anchor=anchor;if(found.empty())result->content.push_back({L"",L"등록된 정보가 없습니다.\r\n조회키 전체 선택과 저장된 CSV를 확인하세요."});for(size_t n=0;n<std::min<size_t>(20,found.size());++n){size_t r=found[n];result->content.push_back({L"@name",wide(data.get(r,"표시명"))});result->content.push_back({L"@key",wide(data.get(r,"분류")+"  /  "+data.get(r,"조회키"))});for(size_t c=0;c<data.columns.size();++c){if(data.columns[c]=="표시명"||data.columns[c]=="분류"||data.columns[c]=="조회키"||data.rows[r][c].empty())continue;result->content.push_back({wide(data.columns[c]),wide(data.rows[r][c])});}if(n+1<std::min<size_t>(20,found.size()))result->content.push_back({L"",L"────────────────"});}if(found.size()>20)result->content.push_back({L"",L"일치 항목이 많아 처음 20개만 표시했습니다. 조회키를 좁혀 주세요."});HWND h=CreateWindowExW(WS_EX_TOOLWINDOW|WS_EX_TOPMOST,L"WorkLookupResult6",L"조회 결과",WS_POPUP|WS_BORDER|WS_VSCROLL,anchor.x,anchor.y,540,300,window,nullptr,instance,result.get());if(!h)throw std::runtime_error("결과 창을 만들 수 없습니다.");result->owned=true;result.release();ShowWindow(h,SW_SHOW);SetForegroundWindow(h);}
